#include <stdio.h>
#include <string.h>

int main() {
  char plaintext[] = "Hello world";
  char ciphertext[20];
  int i;

  printf("Original string: %s\n", plaintext);

  // XOR each character with 127
  for (i = 0; i < strlen(plaintext); i++) {
    ciphertext[i] = plaintext[i] ^ 127;
  }
  ciphertext[i] = '\0';
  printf("After XOR with 127: %s\n", ciphertext);

  // AND each character with 127
  for (i = 0; i < strlen(plaintext); i++) {
    ciphertext[i] = plaintext[i] & 127;
  }
  ciphertext[i] = '\0';
  printf("After AND with 127: %s\n", ciphertext);

  return 0;
}
